import{_ as o,o as a,c,a2 as d}from"./chunks/framework.BkO3HzvX.js";const f=JSON.parse('{"title":"Neony API 参考","description":"","frontmatter":{},"headers":[],"relativePath":"zh/api/index.md","filePath":"zh/api/index.md"}'),n={name:"zh/api/index.md"};function i(t,e,r,l,h,p){return a(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="neony-api-参考" tabindex="-1">Neony API 参考 <a class="header-anchor" href="#neony-api-参考" aria-label="Permalink to &quot;Neony API 参考&quot;">​</a></h1><p>参考文档已拆分为成对章节。每个章节覆盖一个领域，提供短签名、参数、 返回值、边界说明与简短示例；长篇解释放在专题指南中。API 符号、导入 路径、命令与示例文件名在两种语言中均保持英文，便于直接复制代码。</p><h2 id="章节" tabindex="-1">章节 <a class="header-anchor" href="#章节" aria-label="Permalink to &quot;章节&quot;">​</a></h2><ul><li><a href="/neony/zh/api/core.html">核心</a> — <code>NeonApplication</code>、<code>launch</code>、<code>Config</code> / <code>WindowConfig</code> / <code>WebViewConfig</code>、<code>Page</code>、生命周期、多窗口、导航策略、 <code>Tray</code>。</li><li><a href="/neony/zh/api/components.html">组件</a> — 表单控件、文本与标签页、浮层与反馈、 内容组件，以及 <code>Reorder</code> 拖拽重排组件。</li><li><a href="/neony/zh/api/layout-chrome.html">布局与窗口装饰</a> — <code>VStack</code> / <code>HStack</code> / <code>Flex</code> / <code>Separator</code> / <code>GlassPanel</code>、<code>TitleBar</code>、<code>Sidebar</code> / <code>Pane</code> / <code>SidebarGroup</code>、<code>Tree</code>、<code>List</code>、<code>DataTable</code>、<code>Icon</code>。</li><li><a href="/neony/zh/api/dom-css.html">DOM 与 CSS</a> — <code>Color</code>、<code>Styles</code>、<code>DomEvent</code>、原始 HTML 元素与底层拖拽原语。</li><li><a href="/neony/zh/api/reactive.html">响应式</a> — <code>Signal</code>、<code>Computed</code>、<code>effect</code> / <code>Effect</code>、 <code>untrack</code>、<code>SharedSignal</code>、声明式绑定、<code>bind_value</code>、脏子树追踪。</li><li><a href="/neony/zh/api/platform-i18n.html">平台与国际化</a> — 国际化、主题，以及平台原生能力 （窗口控制、原生文件对话框、系统托盘）。</li></ul><h2 id="稳定性" tabindex="-1">稳定性 <a class="header-anchor" href="#稳定性" aria-label="Permalink to &quot;稳定性&quot;">​</a></h2><p>Neony 处于 pre-beta。部分名称仍保留已弃用别名（如 <code>active_key</code> → <code>selected_key</code>）；各章节会在文中标注。逐版本变更见项目 <a href="https://github.com/HarcicYang/Neony/blob/b744352/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a>。</p><p>尚未拆出的精确签名，旧的合并入口暂时保留在 <a href="/neony/zh/api/"><code>api.zh.md</code></a>， 作为稳定链接目标，供读者与外部链接过渡使用。</p>',7)])])}const m=o(n,[["render",i]]);export{f as __pageData,m as default};
